<math ><mtable><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mn>4</mn><mi>𝑚</mi><mo>+</mo><mn>3</mn><mi>𝑚</mi><mo>−</mo><mn>12</mn><mo>−</mo><mn>7</mn><mi>𝑚</mi><mo>−</mo><mn>14</mn></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mi>−</mi><mn>26</mn><mtext mathvariant="normal"> म्हणून पर्याय (3) हे उत्तर. </mtext></mtd></mtr></mtable><annotation encoding="application/x-tex">\begin{matrix}
 &amp; \mathit{\ } = 4\mathit{m} + 3\mathit{m} - 12 - 7\mathit{m} - 14 \\
 &amp; \mathit{\ } = - 26\ \text{~म्हणून पर्याय (3) हे उत्तर.~}
