 &amp; \mathit{\ }\therefore\mathit{A}\mathit{D} = \sqrt{81} = 9
\end{matrix}</annotation></math>
<math display="" xmlns="http://www.w3.org/1998/Math/MathML"><mtable><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><msup><mrow><mi>C</mi><mi>D</mi></mrow><mn>2</mn></msup><mo>=</mo><msup><mrow><mi>C</mi><mi>B</mi></mrow><mn>2</mn></msup><mo>−</mo><msup><mrow><mi>B</mi><mi>D</mi></mrow><mn>2</mn></msup><mo>=</mo><msup><mn>20</mn><mn>2</mn></msup><mo>−</mo><msup><mn>12</mn><mn>2</mn></msup></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mn>400</mn><mo>−</mo><mn>144</mn><mo>=</mo><mn>256</mn></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mtable><mtr><mtd columnalign="center" style="text-align: center"><mo>∴</mo><mi>C</mi><mi>D</mi><mo>=</mo><msqrt><mn>256</mn></msqrt></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mn>16</mn></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"><mi>A</mi><mi>C</mi><mo>=</mo><mi>A</mi><mi>D</mi><mo>+</mo><mi>C</mi><mi>D</mi><mo>=</mo></mtd><mtd columnalign="center" style="text-align: center"><mn>9</mn><mo>+</mo><mn>16</mn><mo>=</mo><mn>25</mn><mi>.</mi><mtext mathvariant="normal"> म्हणून पर्याय (4) हे उत्तर. </mtext></mtd></mtr></mtable></mtd></mtr></mtable><annotation encoding="application/x-tex">\begin{matrix}
 &amp; {CD}^{2} = {CB}^{2} - {BD}^{2} = 20^{2} - 12^{2} \\
 &amp; \  = 400 - 144 = 256 \\
 &amp; \begin{matrix}
\therefore CD = \sqrt{256} &amp; \mathit{\ } = 16 \\
AC = AD + CD = &amp; 9 + 16 = 25.\text{~म्हणून पर्याय (4) हे उत्तर.~}
\end{matrix}
\end{matrix}</annotation></math>

