\therefore(\mathit{a} - 3\mathit{b})^{3} &amp; \mathit{\ } = \mathit{a}^{3} - 3 \times \mathit{a}^{2} \times 3\mathit{b} + 3 \times \mathit{a} \times (3\mathit{b})^{2} - (3\mathit{b})^{3} \\
 &amp; \mathit{\ } = \mathit{a}^{3} - 9\mathit{a}^{2}\mathit{b} + 27\mathit{a}\mathit{b}^{2} - 27\mathit{b}^{3}
\end{matrix}</annotation></math>

d) By using formula
<math display= xmlns="http://www.w3.org/1998/Math/MathML"><mtable><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo stretchy="false" form="prefix">(</mo><mi mathvariant="italic">𝑥</mi><mo>+</mo><mi mathvariant="italic">𝑎</mi><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="prefix">(</mo><mi mathvariant="italic">𝑥</mi><mo>+</mo><mi mathvariant="italic">𝑏</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mi mathvariant="italic">𝑥</mi><mn>2</mn></msup><mo>+</mo><mo stretchy="false" form="prefix">(</mo><mi mathvariant="italic">𝑎</mi><mo>+</mo><mi mathvariant="italic">𝑏</mi><mo stretchy="false" form="postfix">)</mo><mi mathvariant="italic">𝑥</mi><mo>+</mo><mi mathvariant="italic">𝑎</mi><mi mathvariant="italic">𝑏</mi></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo stretchy="false" form="prefix">(</mo><mi mathvariant="italic">𝑥</mi><mo>−</mo><mn>4</mn><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="prefix">(</mo><mi mathvariant="italic">𝑥</mi><mo>+</mo><mn>5</mn><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mi mathvariant="italic">𝑥</mi><mn>2</mn></msup><mo>+</mo><mo stretchy="false" form="prefix">(</mo><mi>−</mi><mn>4</mn><mo>+</mo><mn>5</mn><mo stretchy="false" form="postfix">)</mo><mi mathvariant="italic">𝑥</mi><mo>+</mo><mo stretchy="false" form="prefix">(</mo><mi>−</mi><mn>4</mn><mo stretchy="false" form="postfix">)</mo></mtd><mtd columnalign="center" style="text-align: center"><mtext mathvariant="normal"> </mtext></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><msup><mi mathvariant="italic">𝑥</mi><mn>2</mn></msup><mo>+</mo><mi mathvariant="italic">𝑥</mi><mo>−</mo><mn>20</mn></mtd><mtd columnalign="center" style="text-align: center"><mtext mathvariant="normal"> </mtext></mtd></mtr></mtable><annotation encoding="application/x-tex">\begin{matrix}
 &amp; \mathit{\ }(\mathit{x} + \mathit{a})(\mathit{x} + \mathit{b}) = \mathit{x}^{2} + (\mathit{a} + \mathit{b})\mathit{x} + \mathit{a}\mathit{b} \\
 &amp; \mathit{\ }(\mathit{x} - 4)(\mathit{x} + 5) = \mathit{x}^{2} + ( - 4 + 5)\mathit{x} + ( - 4) &amp; \text{ } \\
 &amp; \mathit{\ } = \mathit{x}^{2} + \mathit{x} - 20 &amp; \text{ }
\end{matrix}</annotation></math>

