∴ Expenditure at the rate
<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>₹</mi><mn>10</mn><mo>=</mo><mn>308</mn><mo>×</mo><mn>10</mn></mrow></math>
<math display=xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mo>=</mo><mi>₹</mi><mn>3080</mn></mrow></math>

c) Volume of water drawn from the tank
<math display=xmlns="http://www.w3.org/1998/Math/MathML"><mtable><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mn>8400</mn><mtext mathvariant="normal"> litre </mtext><mo>=</mo><mfrac><mn>8400</mn><mn>1000</mn></mfrac><msup><mrow><mrow><mtext mathvariant="normal"> </mtext></mrow><mi>m</mi></mrow><mn>3</mn></msup></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mn>8.4</mn><msup><mrow><mrow><mtext mathvariant="normal"> </mtext></mrow><mi>m</mi></mrow><mn>3</mn></msup></mtd></mtr></mtable><annotation encoding="application/x-tex">\begin{matrix}
 &amp; \mathit{\ } = 8400\text{~litre~} = \frac{8400}{1000}{\text{ }m}^{3} \\
 &amp; \mathit{\ } = 8.4{\text{ }m}^{3}
\end{matrix}</annotation></math>
Volume of water drawn from the
<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>t</mi><mi>a</mi><mi>n</mi><mi>k</mi><mo>=</mo><mi mathvariant="italic">𝑙</mi><mo>×</mo><mi>b</mi><mo>×</mo><mi>h</mi></mrow></math>
<math display=xmlns="http://www.w3.org/1998/Math/MathML"><mtable><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mn>8.4</mn><mo>=</mo><mi mathvariant="italic">ℓ</mi><mo>×</mo><mi mathvariant="italic">𝑏</mi><mo>×</mo><mi mathvariant="italic">ℎ</mi><mo>,</mo><mn>8.4</mn><mo>=</mo><mn>7</mn><mo>×</mo><mn>6</mn><mo>×</mo><mi mathvariant="italic">ℎ</mi></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mfrac><mn>8.4</mn><mn>42</mn></mfrac><mo>=</mo><mi mathvariant="italic">ℎ</mi></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mn>0.2</mn><mi mathvariant="italic">𝑚</mi><mo>=</mo><mi mathvariant="italic">ℎ</mi></mtd></mtr></mtable><annotation encoding="application/x-tex">\begin{matrix}
 &amp; 8.4 = \mathit{\ell} \times \mathit{b} \times \mathit{h},8.4 = 7 \times 6 \times \mathit{h} \\
 &amp; \frac{8.4}{42} = \mathit{h} \\
 &amp; 0.2\mathit{m} = \mathit{h}
\end{matrix}</annotation></math>

c) <math display=xmlns="http://www.w3.org/1998/Math/MathML"><mtable><mtr><mtd columnalign="center" style="text-align: center"><mtext mathvariant="normal"> Volume of Godown </mtext></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mi mathvariant="italic">𝐼</mi><mo>×</mo><mi>b</mi><mo>×</mo><mi>h</mi><mo>,</mo></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mn>500</mn><mo>×</mo><mn>160</mn><mo>×</mo><mn>160</mn><msup><mrow><mrow><mtext mathvariant="normal"> </mtext></mrow><mi>c</mi><mi>m</mi></mrow><mn>3</mn></msup></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"><mtext mathvariant="normal"> Volume of one box </mtext></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mn>40</mn><mo>×</mo><mn>40</mn><mo>×</mo><msup><mn>40</mn><mo>−</mo></msup><msup><mrow><mi>c</mi><mi>m</mi></mrow><mn>3</mn></msup></mtd></mtr></mtable><annotation encoding="application/x-tex">\begin{matrix}
\text{~Volume of Godown~} &amp; \mathit{\ } = \mathit{I} \times b \times h, \\
 &amp; \mathit{\ } = 500 \times 160 \times 160{\text{ }cm}^{3} \\
\text{~Volume of one box~} &amp; \mathit{\ } = 40 \times 40 \times 40^{-}{cm}^{3}
\end{matrix}</annotation></math>
<math display=xmlns="http://www.w3.org/1998/Math/MathML"><mtable><mtr><mtd columnalign="center" style="text-align: center"><mtext mathvariant="normal"> Number of boxes </mtext></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mfrac><mtext mathvariant="normal"> Volume of godown </mtext><mtext mathvariant="normal"> Volume of one box </mtext></mfrac></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"></mtd><mtd columnalign="center" style="text-align: center"><mo>=</mo><mfrac><mrow><mn>500</mn><mo>×</mo><mn>160</mn><mo>×</mo><mn>160</mn></mrow><mrow><mn>40</mn><mo>×</mo><mn>40</mn><mo>×</mo><mn>40</mn></mrow></mfrac><mo>=</mo><mn>200</mn></mtd></mtr></mtable><annotation encoding="application/x-tex">\begin{matrix}
\text{~Number of boxes~} &amp; \mathit{\ } = \frac{\text{~Volume of godown~}}{\text{~Volume of one box~}} \\
 &amp; \mathit{\ } = \frac{500 \times 160 \times 160}{40 \times 40 \times 40} = 200
\end{matrix}</annotation></math>
